import{_ as e,o as a,c as r,a4 as d}from"./chunks/framework.CAgiNEKA.js";const p=JSON.parse('{"title":"为什么同一个模型在不同客户端效果不一样？","description":"","frontmatter":{"title":"为什么同一个模型在不同客户端效果不一样？","date":"2026-05-18T00:00:00.000Z","category":"常见问题","tags":["客户端","效果差异","系统提示词"]},"headers":[],"relativePath":"faq/different-clients-different-results.md","filePath":"faq/different-clients-different-results.md","lastUpdated":1779089963000}'),o={name:"faq/different-clients-different-results.md"};function l(s,t,i,n,f,u){return a(),r("div",null,[...t[0]||(t[0]=[d('<h2 id="原因" tabindex="-1">原因 <a class="header-anchor" href="#原因" aria-label="Permalink to &quot;原因&quot;">​</a></h2><p>你调用的是同一个模型，但客户端决定了&quot;模型看到的是什么&quot;。</p><table tabindex="0"><thead><tr><th>影响因素</th><th>说明</th></tr></thead><tbody><tr><td>系统 Prompt</td><td>每个客户端预置了不同的系统提示，有的强调&quot;简洁回答&quot;，有的强调&quot;详细解释&quot;</td></tr><tr><td>上下文裁剪策略</td><td>有的客户端截断历史，有的全量携带，影响模型&quot;记忆&quot;</td></tr><tr><td>temperature 默认值</td><td>有的客户端默认 0.7，有的默认 1.0，影响输出随机性</td></tr><tr><td>Tool Call 开关</td><td>部分客户端默认开启工具调用，会改变模型行为</td></tr><tr><td>消息格式</td><td>不同客户端拼装 messages 的方式有细微差异</td></tr></tbody></table><h2 id="建议" tabindex="-1">建议 <a class="header-anchor" href="#建议" aria-label="Permalink to &quot;建议&quot;">​</a></h2><p>想要稳定一致的输出，建议：</p><ul><li>自己在代码里控制 system prompt，不依赖客户端预置</li><li>固定 temperature 参数</li><li>用 API 直调测试，排除客户端变量</li></ul>',6)])])}const _=e(o,[["render",l]]);export{p as __pageData,_ as default};
